 tools.exec_command({cmd:"rg -n '\\?' apps packages tools --glob '*.ts' --glob '*.tsx' | wc -l; rg -n 'ConditionalExpression|ternary|no-ternary' tools/oxlint docs/standards oxlint.config.ts; sed -n '1,240p' tools/oxlint/site-rules.test.js; ls node_modules/effect/dist/dts/Boolean.d.ts",workdir:"/private/tmp/site-strict-ternary",max_output_tokens:10000})
