import { describe, expect, it } from "vitest";

import siteRules from "./site-rules.js";

const reportsFor = (ruleName, visitorName, node, context = {}) => {
  const reports = [];
  const visitor = siteRules.rules[ruleName].create({
    filename: context.filename,
    getFilename: () => context.filename ?? "",
    report: (report) => {
      reports.push(report.messageId);
    },
  });

  visitor[visitorName]?.(node);

  return reports;
};

const classNameLiteral = (value) => ({
  parent: {
    name: { name: "className", type: "JSXIdentifier" },
    type: "JSXAttribute",
  },
  type: "Literal",
  value,
});

const classBuilderLiteral = (value, calleeName = "cva") => ({
  parent: {
    callee: { name: calleeName, type: "Identifier" },
    type: "CallExpression",
  },
  type: "Literal",
  value,
});

const componentProperty = (componentName) => ({
  key: { name: "component", type: "Identifier" },
  type: "Property",
  value: { name: componentName, type: "Identifier" },
});

describe("site oxlint rules", () => {
  it("flags route-local seo helper calls", () => {
    expect(
      reportsFor("no-route-local-seo", "CallExpression", {
        callee: { name: "seo", type: "Identifier" },
      })
    ).toStrictEqual(["noRouteLocalSeo"]);
  });

  it("flags route-local markdown negotiation imports", () => {
    expect(
      reportsFor("no-route-local-markdown-negotiation", "ImportDeclaration", {
        source: {
          type: "Literal",
          value: "$/lib/seo-aeo/markdown-negotiation",
        },
      })
    ).toStrictEqual(["noRouteLocalMarkdownNegotiation"]);
  });

  it("flags relative imports from a root tool into a package", () => {
    expect(
      reportsFor(
        "no-relative-workspace-imports",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "../../packages/posts/src/schemas",
          },
        },
        { filename: "tools/oxlint/.workspace-boundary.fixture.ts" }
      )
    ).toStrictEqual(["noRelativeWorkspaceImports"]);
  });

  it("flags relative imports between sibling packages", () => {
    expect(
      reportsFor(
        "no-relative-workspace-imports",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "../../scripts/src/site-observability/schemas",
          },
        },
        { filename: "packages/infrastructure/src/schemas.ts" }
      )
    ).toStrictEqual(["noRelativeWorkspaceImports"]);
  });

  it("allows relative imports inside one package and explicit package exports", () => {
    expect(
      reportsFor(
        "no-relative-workspace-imports",
        "ImportDeclaration",
        {
          source: { type: "Literal", value: "./observability/schemas" },
        },
        { filename: "packages/infrastructure/src/stack.ts" }
      )
    ).toStrictEqual([]);
    expect(
      reportsFor(
        "no-relative-workspace-imports",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "@packages/infrastructure/schemas",
          },
        },
        { filename: "apps/web/src/lib/observability/config.ts" }
      )
    ).toStrictEqual([]);
  });

  it("flags unscoped TanStack server function imports", () => {
    expect(
      reportsFor(
        "no-unscoped-tanstack-server-functions",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "@tanstack/react-start",
          },
          specifiers: [
            {
              imported: { name: "createServerFn", type: "Identifier" },
              type: "ImportSpecifier",
            },
          ],
        },
        { filename: "apps/web/src/routes/posts/index.tsx" }
      )
    ).toStrictEqual(["noUnscopedTanstackServerFunctions"]);
  });

  it("allows the documented Markdown middleware server-only fence", () => {
    expect(
      reportsFor(
        "no-unscoped-tanstack-server-functions",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "@tanstack/react-start",
          },
          specifiers: [
            {
              imported: { name: "createServerOnlyFn", type: "Identifier" },
              type: "ImportSpecifier",
            },
          ],
        },
        {
          filename:
            "apps/web/src/lib/http/markdown-sibling-redirect.middleware.ts",
        }
      )
    ).toStrictEqual([]);
  });

  it("keeps the Markdown middleware fence limited to createServerOnlyFn", () => {
    expect(
      reportsFor(
        "no-unscoped-tanstack-server-functions",
        "ImportDeclaration",
        {
          source: {
            type: "Literal",
            value: "@tanstack/react-start",
          },
          specifiers: [
            {
