import { assert, it as effectIt } from "@effect/vitest";
import { Effect } from "effect";
import { describe } from "vitest";

import register from "../../docs/standards/control-register.json";
import bun from "./bun-rules.js";
import effect from "./effect-rules.js";
import mdx from "./mdx-rules.js";
import site from "./site-rules.js";

describe("custom lint control inventory", () => {
  effectIt.effect("maps every custom Oxlint rule exactly once", () =>
    Effect.sync(() => {
      const expected = Object.entries({ bun, effect, mdx, site })
        .flatMap(([namespace, plugin]) =>
          Object.keys(plugin.rules).map((rule) => `${namespace}/${rule}`)
        )
        .toSorted();
      const actual = register.controls
        .filter((control) => expected.includes(control.id))
        .map((control) => control.id)
        .toSorted();
      assert.deepStrictEqual(actual, expected);
      assert.strictEqual(new Set(actual).size, expected.length);
      assert.strictEqual(
        new Set(register.controls.map((control) => control.id)).size,
        register.controls.length
      );
      assert.isTrue(
        register.controls.some(
          (control) => control.id === "DOCUMENTATION-POLICY-CHECK"
        )
      );
      assert.isTrue(
        register.controls.some(
          (control) => control.id === "WORKFLOW-CONTRACT-POLICY"
        )
      );
      assert.strictEqual(expected.length, 59);
    })
  );
});
