  let changed = 0;
  let skipped = 0;
  const render = (node) => {
    if (ts.isConditionalExpression(node)) {
      if (/\byield\b/.test(node.getText(file))) {
        skipped++;
      } else {
        changed++;
        return `Boolean.match(${render(node.condition)}, { onFalse: () => ${render(node.whenFalse)}, onTrue: () => ${render(node.whenTrue)} })`;
