export type Theme = "light" | "dark" | "system";
export type ResolvedTheme = "light" | "dark";

interface ThemeContextValue {
  /** The user's chosen mode. */
  theme: Theme;
  /** What's actually applied right now (system resolves to light/dark). */
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

const STORAGE_KEY = "site-theme";
const DARK_QUERY = "(prefers-color-scheme: dark)";

function readSystemTheme(): ResolvedTheme {
  if (!globalThis.window) {
    return "light";
  }
  return Boolean.match(window.matchMedia(DARK_QUERY).matches, { onFalse: () => ("light"), onTrue: () => ("dark") });
}

function resolveTheme(theme: Theme, system: ResolvedTheme): ResolvedTheme {
  return Boolean.match(theme === "system", { onFalse: () => (theme), onTrue: () => (system) });
}

function applyThemeClass(resolved: ResolvedTheme) {
  if (!globalThis.document) {
    return;
  }
  const root = document.documentElement;
  root.classList.toggle("dark", resolved === "dark");
}

