import { Config, Effect, Schema } from "effect";
import { TaggedError as taggedError } from "effect/Schema";

import { siteSeoAeoConfiguration } from "../seo-aeo/config";

const SiteRequestOriginConfigKey = "SITE_ORIGIN";

const SiteRequestOriginProtocol = Schema.Literals(["http:", "https:"]);

const SiteRequestOriginHost = Schema.NonEmptyString;

const SiteRequestOriginPort = Schema.String.check(
  Schema.isPattern(/^$|^\d+$/u)
);

/**
 * The exported request-origin programs expose this inferred schema type.
 *
 * @public
 */
export const SiteRequestOrigin = Schema.Struct({
  host: SiteRequestOriginHost,
  hostname: SiteRequestOriginHost,
  port: SiteRequestOriginPort,
  protocol: SiteRequestOriginProtocol,
  url: Schema.URLFromString,
});

/**
 * The exported request-origin programs expose this typed failure.
 *
 * @public
 */
export class SiteRequestOriginDecodeError extends taggedError<SiteRequestOriginDecodeError>()(
  "SiteRequestOriginDecodeError",
  {
    input: Schema.String,
    message: Schema.NonEmptyString,
  }
) {}

const decodeSiteRequestOrigin = Schema.decodeUnknownEffect(SiteRequestOrigin);
const decodeUrlFromString = Schema.decodeUnknownEffect(Schema.URLFromString);

const siteRequestOriginConfig = Config.URL(SiteRequestOriginConfigKey).pipe(
  Config.withDefault(new URL(siteSeoAeoConfiguration.identity.baseUrl))
);

export const siteRequestOriginFromUrl = (url: URL) =>
  Effect.gen(function* siteRequestOriginFromUrl() {
    const originUrl = yield* Effect.try({
      catch: () =>
        new SiteRequestOriginDecodeError({
          input: url.href,
          message: `Invalid request origin: ${url.origin}`,
        }),
      try: () => new URL(url.origin),
    });

    return yield* decodeSiteRequestOrigin({
      host: originUrl.host,
      hostname: originUrl.hostname,
      port: originUrl.port,
      protocol: originUrl.protocol,
      url: originUrl.origin,
    }).pipe(
      Effect.mapError(
        (error) =>
          new SiteRequestOriginDecodeError({
            input: originUrl.origin,
            message: String(error),
          })
      )
    );
  });

export const siteRequestOriginFromString = (input: string) =>
  decodeUrlFromString(input).pipe(
    Effect.mapError(
      (error) =>
        new SiteRequestOriginDecodeError({
          input,
          message: String(error),
        })
    ),
    Effect.flatMap(siteRequestOriginFromUrl)
  );

export const configuredSiteRequestOrigin = Effect.gen(
  function* configuredSiteRequestOrigin() {
    const url = yield* siteRequestOriginConfig;
    return yield* siteRequestOriginFromUrl(url);
  }
);
import { assert, it } from "@effect/vitest";
import { ConfigProvider, Effect, Layer, ManagedRuntime } from "effect";
import { HttpServerResponse } from "effect/unstable/http";

import { toManagedRuntimeMachineRouteHandler } from "./effect";
import {
  configuredSiteRequestOrigin,
  siteRequestOriginFromString,
} from "./request-origin";
import { serverRequestOrigin } from "./request-origin.server";

const makeRequestOriginTestHandler = Effect.fn("makeRequestOriginTestHandler")(
  function* () {
    const runtime = yield* Effect.acquireRelease(
      Effect.sync(() => ManagedRuntime.make(Layer.empty)),
      (managedRuntime) => managedRuntime.disposeEffect
    );
    return toManagedRuntimeMachineRouteHandler(runtime);
  }
);

it.effect("resolves localhost and dev origins from the request URL", () =>
  Effect.gen(function* testLocalhostRequestOrigin() {
    const runtimeRouteHandler = yield* makeRequestOriginTestHandler();
    const response = yield* Effect.promise(() =>
      runtimeRouteHandler(
        serverRequestOrigin.pipe(
          Effect.map((origin) => HttpServerResponse.text(origin.url.origin))
        )
      )(new Request("http://127.0.0.1:4592/posts/hello-world"))
    );
    const body = yield* Effect.promise(() => response.text());

    assert.strictEqual(response.status, 200);
    assert.strictEqual(body, "http://127.0.0.1:4592");
  })
);

it.effect(
  "resolves forwarded host and proto through HttpServerRequest.toURL",
  () =>
    Effect.gen(function* testForwardedRequestOrigin() {
      const runtimeRouteHandler = yield* makeRequestOriginTestHandler();
      const response = yield* Effect.promise(() =>
        runtimeRouteHandler(
          serverRequestOrigin.pipe(
            Effect.map((origin) => HttpServerResponse.text(origin.url.origin))
          )
        )(
          new Request("http://internal.local/posts/hello-world", {
            headers: {
              host: "site.local",
              "x-forwarded-proto": "https",
            },
          })
        )
      );
      const body = yield* Effect.promise(() => response.text());

      assert.strictEqual(response.status, 200);
      assert.strictEqual(body, "https://site.local");
    })
);

it.effect(
{
  "extends": "../../tsconfig.base.json",
