const strictEffectScopeSentinels = [
  "effect/no-async-await-promise",
  "effect/no-bare-effect-try-promise",
  "effect/no-nested-wrapper-calls",
  "effect/no-nullish-comparison",
  "effect/no-schema-decoder-outside-ingress",
  "effect/no-schema-encoder-outside-egress",
  "effect/no-throw",
  "effect/no-throwing-schema-sync-codec",
];

describe("installed Oxlint plugin integration", () => {
  effectIt.effect("keeps the repository check warning-free", () =>
    Effect.gen(function* warningFreeRepositoryCheckContract() {
      const fileSystem = yield* FileSystem.FileSystem;
      const manifest = yield* Schema.decodeEffect(PackageCheckScript)(
        yield* fileSystem.readFileString(
          new URL("../../package.json", import.meta.url)
        )
      );
      assert.include(manifest.scripts.check, "--deny-warnings");
    }).pipe(Effect.provide(BunServices.layer))
  );
  effectIt.effect(
    "keeps JavaScript redeclaration checks without rejecting TypeScript value/type pairs",
    () =>
