          results[1]?.contentType,
          "text/markdown; charset=utf-8"
        );
        assert.strictEqual(results[2]?.contentType, "image/png");
        assert.deepStrictEqual(
          Option.fromUndefinedOr(results[2]).pipe(
            Option.match({
              onNone: () => undefined,
              onSome: (result) => {
                if (result.kind === "og") {
                  return result.dimensions;
                }
                return undefined;
              },
            })
          ),
          { height: 630, width: 1200 }
        }
        return child;
      },
      destroyTmp,
      kill,
      launch,
      get port() {
        return Boolean.match(Number.isNaN(port), {
          onFalse: () => port,
          onTrue: () => undefined,
        });
      },
    };
  };

  reset();
