import { SignalCanvas } from "$/lib/signal-playground/canvas";
import {
  presetSettings,
  presets,
  settingsJson,
} from "$/lib/signal-playground/settings";
import type { SignalSettings } from "$/lib/signal-playground/settings";
import { shuffleSettings } from "$/lib/signal-playground/settings.runtime";
import { Button } from "@packages/ui/components/button";
import { Heading, Text } from "@packages/ui/components/typography";
import { createFileRoute } from "@tanstack/react-router";
import { Boolean, Result, Schema } from "effect";
import { useState } from "react";

import playgroundCss from "$/lib/signal-playground/style.css?url";

export const Route = createFileRoute("/playground")({
  component: SignalPlayground,
  head: () => ({
    meta: [
      { title: "Signal playground · Cooper Corbett" },
      { name: "robots", content: "noindex, nofollow" },
    ],
    links: [{ rel: "stylesheet", href: playgroundCss }],
    request: Request,
    operation: () => Promise<A>,
    statusFor: (value: A) => Option.Option<number>
  ) {
    const startStage = Boolean.match(operationName === "site.http.request", {
      onFalse: () => "started",
      onTrue: () => "received",
    });
    yield* emit(request, operationName, startStage);
    return yield* withSiteRequestContext(operation).pipe(
      Effect.onExit((exit) => {
        if (Exit.isSuccess(exit)) {
          const status = statusFor(exit.value);
          return emit(request, operationName, "completed", status);
        }
        const failureStage = Boolean.match(request.signal.aborted, {
          onFalse: () => "failed",
          onTrue: () => "cancelled",
        });
        return emit(request, operationName, failureStage);
      })
    );
  });

