function downloadFile(href: string, name: string) {
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.download = name;
  anchor.click();
}

function SignalPlayground() {
  const [settings, setSettings] = useState(() => presetSettings(0));
  const [view, setView] = useState<"artwork" | "compare" | "footer">("compare");
  const [playing, setPlaying] = useState(false);
  const [json, setJson] = useState("");
  const [message, setMessage] = useState("");
  const [paper, setPaper] = useState(false);
  const preset = presets[settings.preset];
  const update = <K extends keyof SignalSettings>(
    key: K,
    value: SignalSettings[K]
  ) => setSettings((previous) => ({ ...previous, [key]: value }));
  const exportSettings = () => {
    const encoded = Schema.encodeSync(settingsJson)(settings);
    setJson(encoded);
    setMessage(
      "Settings are ready below. Keep a copy to recreate this variant."
    );
    downloadFile(
      `data:application/json;charset=utf-8,${encodeURIComponent(encoded)}`,
      "signal-settings.json"
    );
  };
  const importSettings = () => {
    const decoded = Schema.decodeResult(settingsJson)(json);
    if (Result.isFailure(decoded)) {
      setMessage(
        "These settings are invalid. Paste a complete exported settings file with values inside the slider ranges."
      );
      return;
    }
    setSettings(decoded.success);
    setPlaying(false);
    setMessage("Settings restored.");
  };
  return (
    <main className="signal-lab">
      <header className="signal-heading">
        <div>
          <Text variant="mono-label" tone="muted">
            background studies / 01—04
          </Text>
          <Heading level={1} variant="display">
            Signal playground
          </Heading>
          <Text tone="muted">
            Shape the light. Tune the texture. Find a quieter signal.
          </Text>
        </div>
        <Text variant="caption" tone="muted">
          Generated live · no image textures
        </Text>
      </header>
      <div className="signal-presets" aria-label="Reference presets">
        {([0, 1, 2, 3] as const).map((id) => (
          <button
            type="button"
            key={id}
            aria-pressed={settings.preset === id}
            onClick={() => {
              setSettings(presetSettings(id));
              setPlaying(false);
              setMessage("");
            }}
          >
            <span className="mono-label">0{id + 1}</span>
            <span className="type-label">{presets[id]?.name}</span>
            <span className="signal-preset-mark" aria-hidden="true" />
          </button>
        ))}
      </div>
      <div className="signal-workspace">
        <section className="signal-preview" aria-label="Background preview">
          <div className="signal-toolbar">
            <div className="signal-view" aria-label="Preview layout">
