  "rg -n 'alchemy-main|quality_sha|workflow_call|production|release' .github/workflows",
  "git status --short --branch",
  "gh pr view 131 --json number,state,mergeStateStatus,mergeable,headRefOid,baseRefOid,reviewDecision,statusCheckRollup"
];
const r = await Promise.allSettled(cmds.map(cmd => tools.exec_command({cmd,workdir:"/private/tmp/site-strict-ternary",yield_time_ms:30000,max_output_tokens:6500})));
r.forEach((v,i)=>text(JSON.stringify({cmd:cmds[i],result:v})));

