  "cat .github/workflows/alchemy-main.yml",
  "rg -n 'release:tags|Changeset|tag|release workflow|Production delivery|production deploy|deploy.*prod' docs/runbooks docs/architecture/deployment.md | head -100",
  "gh api repos/crcorbett/site/environments/production --jq '{name,protection_rules,wait_timer}'"
];
const r = await Promise.allSettled(cmds.map(cmd => tools.exec_command({cmd,workdir:"/private/tmp/site-strict-ternary",yield_time_ms:30000,max_output_tokens:5000})));
