payload.input:
const cmds=[
  "curl --silent --show-error --location --output /private/tmp/site-release-home.html --write-out 'apex status=%{http_code} final=%{url_effective} content_type=%{content_type}\\n' https://coopercorbett.com/",
  "curl --silent --show-error --output /dev/null --write-out 'www status=%{http_code} redirect=%{redirect_url}\\n' https://www.coopercorbett.com/",
  "curl --silent --show-error --location --output /dev/null --write-out 'now status=%{http_code} final=%{url_effective} content_type=%{content_type}\\n' https://coopercorbett.com/now"
];
const r=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/private/tmp/site-strict-ternary",sandbox_permissions:"require_escalated",justification:"Read the public Site apex, www redirect and Now page after the successful Production deploy.",prefix_rule:["curl"],yield_time_ms:30000,max_output_tokens:1000})));r.forEach((v,i)=>text(JSON.stringify({cmd:cmds[i],result:v})));

const cmds=[
  "curl --silent --show-error --location --output /dev/null --write-out 'css status=%{http_code} content_type=%{content_type} bytes=%{size_download}\\n' https://coopercorbett.com/assets/app-DpZGvlk5.css",
  "curl --silent --show-error --location --output /dev/null --write-out 'js status=%{http_code} content_type=%{content_type} bytes=%{size_download}\\n' https://coopercorbett.com/assets/index-BRLhD0tA.js",
  "gh api repos/crcorbett/site/commits/main --jq .sha"
];
const r=await Promise.allSettled(cmds.map((cmd,i)=>tools.exec_command({cmd,workdir:"/private/tmp/site-strict-ternary",sandbox_permissions:"require_escalated",justification:i<2?"Check real CSS and JavaScript links served by the deployed public page.":"Confirm main still points at the released commit.",prefix_rule:i<2?["curl"]:["gh","api"],yield_time_ms:30000,max_output_tokens:700})));r.forEach((v,i)=>text(JSON.stringify({cmd:cmds[i],result:v})));

const cmds=[
  "gh pr view 3 --json number,state,updatedAt,headRefOid,title,url --jq '{number,state,updatedAt,headRefOid,title,url}'",
  "gh run view 35942300876 --json jobs --jq '[.jobs[]|select(.name==\"alchemy / Deploy Production Alchemy graph\" or .name==\"release / Release\")|{name,databaseId,conclusion,completedAt}]'"
];
const r=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/private/tmp/site-strict-ternary",sandbox_permissions:"require_escalated",justification:"Capture final release metadata and Production job receipts.",prefix_rule:["gh"],yield_time_ms:30000,max_output_tokens:1000})));r.forEach((v,i)=>text(JSON.stringify({cmd:cmds[i],result:v})));
